export const PHASE_LABEL_VI = { solid: 'Rắn', liquid: 'Lỏng', gas: 'Khí' };

export const ELEMENT_BY_ID = Object.fromEntries(ELEMENTS.map((e) => [e.id, e]));

export const ELEMENT_BY_SYMBOL = Object.fromEntries(
  ELEMENTS.map((e) => [e.symbol.toLowerCase(), e])
);

export function getElement(elementId) {
  return ELEMENT_BY_ID[elementId] ?? null;
}

// 'metal' | 'nonmetal' | 'metalloid'
export function getElementKind(element) {
  return CATEGORY_INFO[element.category].kind;
}
